mapper.sql:
AND EXISTS (
SELECT 1
FROM product_desk_attributes da
WHERE da.product_id = p.product_id

    AND da.top_shape_id IN

        #{value}



    AND da.taste_id IN

        #{value}



    AND (



                da.width_mm <= #{range.maxInclusive}


                da.width_mm >= #{range.minInclusive}


                (da.width_mm >= #{range.minInclusive} AND da.width_mm <= #{range.maxInclusive})



    )


    AND (



                da.depth_mm <= #{range.maxInclusive}


                da.depth_mm >= #{range.minInclusive}


                (da.depth_mm >= #{range.minInclusive} AND da.depth_mm <= #{range.maxInclusive})



    )


    AND (



                da.height_mm <= #{range.maxInclusive}


                da.height_mm >= #{range.minInclusive}


                (da.height_mm >= #{range.minInclusive} AND da.height_mm <= #{range.maxInclusive})



    )

)

AND EXISTS (
SELECT 1
FROM product_chair_attributes ca
WHERE ca.product_id = p.product_id

    AND ca.function_id IN

        #{value}



    AND ca.material_id IN

        #{value}



    AND ca.taste_id IN

        #{value}


)

AND EXISTS (
SELECT 1
FROM product_storage_attributes sa
WHERE sa.product_id = p.product_id

    AND sa.usage_id IN

        #{value}



    AND sa.taste_id IN

        #{value}


)

p.sale_start_at <= #{now}
AND (p.sale_end_at IS NULL OR p.sale_end_at > #{now})

    AND p.sale_start_at >= #{saleStartFrom}


    AND p.category_id = #{categoryId}


    AND (
    p.product_name ILIKE #{keywordLike}
    OR EXISTS (
    SELECT 1
    FROM product_variants pvk
    WHERE pvk.product_id = p.product_id
    AND pvk.product_code ILIKE #{keywordCodeLike}
    )
    )


    AND EXISTS (
    SELECT 1
    FROM product_variants pvf
    WHERE pvf.product_id = p.product_id

    )

mapper.select:
SELECT p.product_id, p.product_name, MIN(pv.unit_price) AS min_price, MAX(pv.stock_quantity) AS max_stock, MIN(pv.product_code) AS product_code, COALESCE(( SELECT AVG(pr.rating) FROM product_reviews pr WHERE pr.product_id = p.product_id AND pr.is_published = TRUE ), 0) AS average_rating, ( SELECT COUNT(*) FROM product_reviews pr WHERE pr.product_id = p.product_id AND pr.is_published = TRUE ) AS review_count FROM products p JOIN product_variants pv ON pv.product_id = p.product_id LEFT JOIN product_reviews pr ON pr.product_id = p.product_id AND pr.is_published = TRUE WHERE p.product_id IN
#{productId}
AND p.sale_start_at <= #{now} AND (p.sale_end_at IS NULL OR p.sale_end_at > #{now}) GROUP BY p.product_id, p.product_name

SELECT pv.product_id, c.color_code, c.sort_order FROM product_variants pv JOIN colors c ON c.color_id = pv.color_id WHERE pv.product_id IN
#{productId}
ORDER BY pv.product_id ASC, c.sort_order ASC
